  (I J : Ideal ↑(X.presheaf.obj (Opposite.op U))) :
  X.zeroLocus ↑(I ⊓ J) = X.zeroLocus ↑I ∪ X.zeroLocus ↑J

theorem AlgebraicGeometry.IsAffineOpen.fromSpec_preimage_basicOpen.{u} {X : AlgebraicGeometry.Scheme}
  {U : X.Opens} (hU : AlgebraicGeometry.IsAffineOpen U) (f : ↑(X.presheaf.obj (Opposite.op U))) :
  (TopologicalSpace.Opens.map hU.fromSpec.base).obj (X.basicOpen f) = PrimeSpectrum.basicOpen f

