theorem AlgebraicGeometry.Scheme.zeroLocus_biInf.{u, u_1} {X : AlgebraicGeometry.Scheme} {U : X.Opens}
  {ι : Type u_1} (I : ι → Ideal ↑(X.presheaf.obj (Opposite.op U))) {t : Set ι} (ht : t.Finite) :
  X.zeroLocus ↑(⨅ i ∈ t, I i) = (⋃ i ∈ t, X.zeroLocus ↑(I i)) ∪ (↑U)ᶜ

